using System.Net; using System.Text; using System.Text.Json; using System.Windows; namespace CloudServer; internal static class Program { [STAThread] static void Main(){var store=new StateStore();Task.Run(()=>Api.Run(store));var app=new App();app.InitializeComponent();app.Run(new AdminWindow(store));} }
public static class Api {
 static readonly JsonSerializerOptions json=new(JsonSerializerDefaults.Web);
 public static async Task Run(StateStore store){var l=new HttpListener();l.Prefixes.Add("http://localhost:5050/");l.Start();while(true){var c=await l.GetContextAsync();_=Task.Run(()=>Handle(c,store));}}
 static async Task Handle(HttpListenerContext c,StateStore store){try{var p=c.Request.Url?.AbsolutePath??"/";if(p=="/api/health"){await Reply(c,200,new{status="ok",product="i-NET-PROMO Cloudservice"});return;}if(p=="/api/login"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<Login>(c.Request.InputStream,json);var u=store.State.Users.FirstOrDefault(x=>x.UserName.Equals(q?.UserName,StringComparison.OrdinalIgnoreCase));if(u==null||!StateStore.Verify(q?.Password??"",u.PasswordHash)){await Reply(c,401,new{error="Anmeldung fehlgeschlagen"});return;}await Reply(c,200,new{u.Id,u.UserName,u.DisplayName,u.IsAdmin,u.QuotaBytes});return;}if(p=="/api/users"){await Reply(c,200,store.State.Users.Select(u=>new{u.Id,u.UserName,u.DisplayName,u.IsAdmin,u.QuotaBytes}));return;}if(p=="/api/storage"){await Reply(c,200,store.State.Storage);return;}
if(p=="/api/shares"&&c.Request.HttpMethod=="GET"){await Reply(c,200,store.State.Shares.Select(s=>new{s.Id,s.OwnerUserId,s.TargetUserId,s.StorageId,s.RelativePath,s.CanWrite,s.CreatedUtc}));return;}
if(p=="/api/shares"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<ShareRequest>(c.Request.InputStream,json);if(q==null||!store.State.Users.Any(u=>u.Id==q.TargetUserId)||!store.State.Storage.Any(s=>s.Id==q.StorageId)){await Reply(c,400,new{error="Ungültige Freigabe"});return;}var grant=new ShareGrant{OwnerUserId=q.OwnerUserId,TargetUserId=q.TargetUserId,StorageId=q.StorageId,RelativePath=q.RelativePath??"",CanWrite=q.CanWrite};store.State.Shares.Add(grant);store.Save();await Reply(c,201,grant);return;}await Reply(c,404,new{error="Not found"});}catch(Exception e){await Reply(c,500,new{error=e.Message});}}
 static async Task Reply(HttpListenerContext c,int status,object o){var b=Encoding.UTF8.GetBytes(JsonSerializer.Serialize(o,json));c.Response.StatusCode=status;c.Response.ContentType="application/json; charset=utf-8";c.Response.ContentLength64=b.Length;await c.Response.OutputStream.WriteAsync(b);c.Response.Close();}
 sealed record Login(string UserName,string Password); sealed record ShareRequest(string OwnerUserId,string TargetUserId,string StorageId,string? RelativePath,bool CanWrite);
}
